pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }

    // fuzzed params: baseToken and nft addresses and some numeric params
    function testFuzz_property(address baseToken, address nftAddr, uint128 vBase, uint128 vNft, uint56 changeFee, uint16 feeRate, bytes32 merkleRoot, bool useStolen, bool payRoyalties) public {
        // keep feeRate within admissible wide bounds
        if (feeRate > type(uint16).max) feeRate = feeRate; // noop to satisfy fuzzer usage
        vm.assume(feeRate <= 60000); // still wide; reference requires <=5000 but we let initialize check that

        // call initialize and capture whether it succeeded
        bool ok;
        try c.initialize(baseToken, nftAddr, vBase, vNft, changeFee, feeRate, merkleRoot, useStolen, payRoyalties) {
            ok = true;
        } catch {
            ok = false;
        }

        // If initialize reverted (e.g., feeRate > 5000 or already initialized), nothing further guaranteed.
        // We only assert when initialize returned successfully: then nft() must equal the _nft argument passed.
        if (ok) {
            // single assertion: after successful initialize, c.nft() equals the nftAddr argument
            assertTrue(c.nft() == nftAddr);
        } else {
            // if initialize reverted, still assert that it did revert (ok==false) is allowed — no further check
            assertTrue(ok == false);
        }
    }
}

