pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }

    // Fuzz parameters include the _nft address and other typical initialize args.
    function testFuzz_property(address _baseToken, address _nft, uint128 _virtualBaseTokenReserves, uint128 _virtualNftReserves, uint56 _changeFee, uint16 _feeRate, bytes32 _merkleRoot, bool _useStolenNftOracle, bool _payRoyalties) public {
        // keep domain wide but avoid trivial invalid feeRate > 5000 because both implementations revert on that
        if (_feeRate > 5000) return;

        // Call initialize and observe whether after the call c.nft() equals the _nft argument.
        bool ok;
        try c.initialize(_baseToken, _nft, _virtualBaseTokenReserves, _virtualNftReserves, _changeFee, _feeRate, _merkleRoot, _useStolenNftOracle, _payRoyalties) {
            ok = true;
        } catch {
            // if initialize reverts, we consider the input inadmissible for this property; do not assert
            return;
        }

        // Single assertion: reference always sets nft() == _nft; mutant will differ for some inputs
        assertTrue(ok && (c.nft() == _nft));
    }
}

