import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }

    // fuzz: pass in the _nft argument (address) and a feeRate to keep feeRate within bounds
    function testFuzz_property(address nftArg, uint16 feeRate) public {
        // keep feeRate admissible
        feeRate = uint16(bound(feeRate, 0, 5000));

        // avoid zero address for nftArg? We keep wide: allow zero as valid input too.

        // Call initialize with fuzzed nftArg and other arbitrary valid values
        // Use try/catch to ensure we capture whether initialize reverts (it shouldn't under these inputs)
        bool ok;
        try c.initialize(
            address(0), // _baseToken
            nftArg, // _nft (fuzzed)
            uint128(1), // _virtualBaseTokenReserves
            uint128(1), // _virtualNftReserves
            uint56(0), // _changeFee
            feeRate, // _feeRate (bounded)
            bytes32(0), // _merkleRoot
            false, // _useStolenNftOracle
            false  // _payRoyalties
        ) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference always returns ok==true and then c.nft() equals nftArg.
        // We assert a single property that must hold for the reference for ALL inputs
        // and which the mutant will violate for some input: if initialize succeeded, then c.nft() == nftArg.
        // If initialize reverted then the post-state is irrelevant; we only assert when it succeeded.
        if (ok) {
            assertTrue(c.nft() == nftArg);
        } else {
            // If initialize reverted (shouldn't for admissible feeRate), still assert that nft remains default (address(0)).
            // However to keep a single assertion per run we still use assertTrue with a condition that is true for the reference.
            // Reference: initialize reverts only when already initialized or feeRate > 5000; here feeRate <= 5000 and c not initialized.
            // Therefore ok should always be true for the reference; this branch will not be taken for the reference.
            assertTrue(c.nft() == address(0));
        }
    }
}

