pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this), address(this), address(this)); }

    // Fuzzed parameter is the _nft address passed to initialize. The property:
    // Reference: after initialize(..., _nft, ...) c.nft() == _nft for ALL inputs.
    // Mutant: sometimes c.nft() != _nft (it sets nft from Factory(factory).ownerOf(...)).
    function testFuzz_property(address _nft) public {
        // Keep domain wide but avoid zero address to ensure sensible _nft values are allowed.
        // Zero address is still admissible in original contract, so we do NOT exclude it.

        // other initialize params set to arbitrary valid values
        address baseToken = address(0);
        uint128 virtualBaseTokenReserves = 1;
        uint128 virtualNftReserves = 1;
        uint56 changeFee = 0;
        uint16 feeRate = 0;
        bytes32 merkleRoot = bytes32(0);
        bool useStolenNftOracle = false;
        bool payRoyalties = false;

        bool ok;
        try c.initialize(
            baseToken,
            _nft,
            virtualBaseTokenReserves,
            virtualNftReserves,
            changeFee,
            feeRate,
            merkleRoot,
            useStolenNftOracle,
            payRoyalties
        ) {
            ok = true;
        } catch {
            ok = false;
        }

        // Single assertion: when initialize succeeded, the stored nft() must equal the _nft argument.
        // The correct contract always satisfies this for all inputs; the mutant violates it for some _nft
        // because it instead writes Factory(factory).ownerOf(uint160(address(this))).
        if (ok) {
            assertTrue(c.nft() == _nft);
        } else {
            // If initialize reverted, still assert that nft() is not set to some other value (leave trivial):
            // but we must have exactly one assertTrue, so we assert a true constant when init failed is not allowed.
            // To satisfy the requirement of exactly one assertTrue reading c, we convert the failure case into
            // an assertion about nft() still equaling its default (address(0)). The reference contract sets nft
            // only on successful initialize, so when initialize reverts nft() remains address(0); the mutant also
            // would keep it address(0). Thus this branch will hold for both, and does not mask the distinguishing case.
            assertTrue(c.nft() == address(0));
        }
    }
}

